12	#include "tiling/platform/platform_ascendc.h"
13	#include "aclrtlaunch_matmul_leakyrelu_fp16.h"
14	#include "matmul_leakyrelu_tiling.h"
15	
16	namespace ascend_kernel {
17	
18	static inline int64_t GetWorkspaceSize(const MatmulLeakyReluTiling *tiling, int accElementSize,
19	                                       uint32_t usedCoreNum)
20	{
21	    // Try 8 (Bulk Sync): flat M×N workspace, shared across block groups (non-overlapping tiles).
22	    (void)usedCoreNum;
23	    return static_cast<int64_t>(tiling->M) * tiling->N * accElementSize;
24	}
25	
26	at::Tensor matmul_leakyrelu(const at::Tensor &a, const at::Tensor &b)
27	{
28	    TORCH_CHECK(a.dim() == 2, "matmul_leakyrelu a must be two-dimensional.");
29	    TORCH_CHECK(b.dim() == 2, "matmul_leakyrelu b must be two-dimensional.");
30	    TORCH_CHECK(a.sizes()[1] == b.sizes()[0], "matmul_leakyrelu k must be same.");
31	    TORCH_CHECK(a.scalar_type() == b.scalar_type(), "matmul_leakyrelu a and b must have same dtype.");
32	
33	    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
34	    uint32_t usedCoreNum = ascendcPlatform->GetCoreNumAic();
35	    uint32_t m = static_cast<uint32_t>(a.sizes()[0]);
36	    uint32_t n = static_cast<uint32_t>(b.sizes()[1]);
37	    uint32_t k = static_cast<uint32_t>(a.sizes()[1]);
38	
39	    at::Tensor c = at::empty({static_cast<int64_t>(m), static_cast<int64_t>(n)},
40	                             at::device(at::kPrivateUse1).dtype(at::kFloat));
41	
42	    at::Tensor t = at::empty({static_cast<int64_t>(sizeof(MatmulLeakyReluTiling))},
43	                             at::device(at::kCPU).dtype(at::kByte));
44	    auto *tiling_ptr = reinterpret_cast<MatmulLeakyReluTiling *>(t.data_ptr());
45	    tiling_ptr->M = static_cast<int32_t>(m);
46	    tiling_ptr->N = static_cast<int32_t>(n);
47	    tiling_ptr->K = static_cast<int32_t>(k);
48	    tiling_ptr->baseM = DEFAULT_BASE_M;
49	    tiling_ptr->baseN = DEFAULT_BASE_N;
50	    tiling_ptr->baseK = DEFAULT_BASE_K;
51	    tiling_ptr->l1Prefetch = DEFAULT_L1_PREFETCH;
52	    auto tiling_npu = t.to(at::kPrivateUse1);
53	
54	    uint32_t blockDim = usedCoreNum;
55	
56	    int accElementSize = sizeof(float);
57	    int64_t workSpaceSize = GetWorkspaceSize(tiling_ptr, accElementSize, usedCoreNum);
58	    at::Tensor w = at::empty({workSpaceSize}, at::device(at::kPrivateUse1).dtype(at::kByte));
59	    EXEC_KERNEL_CMD(matmul_leakyrelu_fp16, blockDim, a, b, c, w, tiling_npu);
60	
61	    return c;
62	}
63	
64	} // namespace ascend_kernel
