11	/* !
12	 * \file mul.asc
13	 * \brief 演示使用Mul接口实现向量逐元素乘法计算功能，采用4核并行模式
14	 */
15	
16	#include "acl/acl.h"
17	#include "kernel_operator.h"
18	#include "utils/std/cmath.h"
