21	constexpr uint32_t totalLength = 1024;
22	constexpr uint32_t singleCoreLength = totalLength / 4;
23	
24	template <typename T>
25	__simd_vf__ inline void MulVF(
26	    __ubuf__ T* xAddr, __ubuf__ T* yAddr, __ubuf__ T* zAddr, uint32_t repeatTimes, uint32_t oneRepeatSize)
27	{
28	    AscendC::Reg::MaskReg mask = AscendC::Reg::CreateMask<T, AscendC::Reg::MaskPattern::ALL>();
29	    AscendC::Reg::RegTensor<T> xReg, yReg, zReg;
30	    for (uint16_t i = 0; i < repeatTimes; ++i) {
31	        AscendC::Reg::LoadAlign(xReg, xAddr + i * oneRepeatSize);
32	        AscendC::Reg::LoadAlign(yReg, yAddr + i * oneRepeatSize);
33	        AscendC::Reg::Mul(zReg, yReg, xReg, mask);
34	        AscendC::Reg::StoreAlign(zAddr + i * oneRepeatSize, zReg, mask);
35	    }
36	}
37	
38	template <typename T, uint32_t singleCoreLength>
39	class KernelMul {
40	public:
41	    __aicore__ inline void Init(__gm__ uint8_t* x, __gm__ uint8_t* y, __gm__ uint8_t* z)
42	    {
43	        xGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(x));
44	        yGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(y));
45	        zGm.SetGlobalBuffer(reinterpret_cast<__gm__ T*>(z));
46	    }
47	
48	    __aicore__ inline uint32_t GetCoreOffset() { return AscendC::GetBlockIdx() * singleCoreLength; }
49	
50	    __aicore__ inline void Process()
51	    {
52	        uint32_t coreOffset = GetCoreOffset();
53	
54	        AscendC::LocalMemAllocator<AscendC::Hardware::UB> ubAllocator;
55	        AscendC::LocalTensor<T> xLocal = ubAllocator.Alloc<T, singleCoreLength>();
56	        AscendC::LocalTensor<T> yLocal = ubAllocator.Alloc<T, singleCoreLength>();
57	        AscendC::LocalTensor<T> zLocal = ubAllocator.Alloc<T, singleCoreLength>();
58	
59	        AscendC::DataCopy(xLocal, xGm[coreOffset], singleCoreLength);
60	        AscendC::DataCopy(yLocal, yGm[coreOffset], singleCoreLength);
61	        AscendC::SetFlag<AscendC::HardEvent::MTE2_V>(EVENT_ID0);
62	        AscendC::WaitFlag<AscendC::HardEvent::MTE2_V>(EVENT_ID0);
63	
64	        __ubuf__ T* xAddr = reinterpret_cast<__ubuf__ T*>(xLocal.GetPhyAddr());
65	        __ubuf__ T* yAddr = reinterpret_cast<__ubuf__ T*>(yLocal.GetPhyAddr());
66	        __ubuf__ T* zAddr = reinterpret_cast<__ubuf__ T*>(zLocal.GetPhyAddr());
67	        constexpr uint32_t oneRepeatSize = AscendC::GetVecLen() / sizeof(T);
68	        uint16_t repeatTimes = static_cast<uint16_t>(AscendC::Std::ceil_div(singleCoreLength, oneRepeatSize));
69	
70	        asc_vf_call<MulVF<T>>(xAddr, yAddr, zAddr, repeatTimes, oneRepeatSize);
71	
72	        AscendC::SetFlag<AscendC::HardEvent::V_MTE3>(EVENT_ID0);
73	        AscendC::WaitFlag<AscendC::HardEvent::V_MTE3>(EVENT_ID0);
74	
75	        AscendC::DataCopy(zGm[coreOffset], zLocal, singleCoreLength);
76	    }
77	
78	private:
79	    AscendC::GlobalTensor<T> xGm;
80	    AscendC::GlobalTensor<T> yGm;
81	    AscendC::GlobalTensor<T> zGm;
82	};
83	
84	__global__ __vector__ void mul(__gm__ uint8_t* x, __gm__ uint8_t* y, __gm__ uint8_t* z)
85	{
86	    AscendC::InitSocState();
87	    KernelMul<float, singleCoreLength> kernel;
88	    kernel.Init(x, y, z);
89	    kernel.Process();
90	    AscendC::PipeBarrier<PIPE_ALL>();
91	}
