93	static bool CompareResult(const void* outputData, uint32_t outSize)
94	{
95	    void* goldenData;
96	    aclrtMallocHost((void**)(&goldenData), outSize);
97	    size_t goldenSize = outSize;
98	    bool ret = ReadFile("./output/golden.bin", goldenSize, goldenData, goldenSize);
99	    if (ret) {
100	        printf("ReadFile golden.bin success!\n");
101	    } else {
102	        printf("test failed!\n");
103	        aclrtFreeHost(goldenData);
104	        return false;
105	    }
106	    constexpr float EPS = 1e-4;
107	    int64_t wrongNum = 0;
108	
109	    for (size_t i = 0; i < outSize / sizeof(float); i++) {
110	        float a = (reinterpret_cast<const float*>(outputData))[i];
111	        float b = (reinterpret_cast<const float*>(goldenData))[i];
112	        float ae = std::abs(a - b);
113	        float re = ae / std::abs(b);
114	        if (ae > EPS && re > EPS) {
115	            printf("CompareResult golden.bin failed output is %lf, golden is %lf\n", a, b);
116	            wrongNum++;
117	        }
118	    }
119	    aclrtFreeHost(goldenData);
120	    if (wrongNum != 0) {
121	        return false;
122	    } else {
123	        printf("CompareResult golden.bin success!\n");
124	        return true;
125	    }
126	}
