150	    aclrtMemcpy(yDevice, inputByteSize, yHost, inputByteSize, ACL_MEMCPY_HOST_TO_DEVICE);
151	    mul<<<numBlocks, 0, stream>>>(xDevice, yDevice, zDevice);
152	    aclrtSynchronizeStream(stream);
153	    aclrtMemcpy(zHost, outputByteSize, zDevice, outputByteSize, ACL_MEMCPY_DEVICE_TO_HOST);
154	    WriteFile("./output/output.bin", zHost, outputByteSize);
155	    bool goldenResult = CompareResult(zHost, outputByteSize);
156	    if (goldenResult) {
