37	class MatmulLeakyKernel {
38	public:
39	    __aicore__ inline MatmulLeakyKernel() {}
40	    __aicore__ inline void Init(GM_ADDR a, GM_ADDR b, GM_ADDR c, GM_ADDR ws, GM_ADDR tGM);
41	    __aicore__ inline void Process();
