45	    GlobalTensor<bType> bGM_;
46	    GlobalTensor<outType> cGM_;
47	    GlobalTensor<accType> wsGM_;
48	    MatmulLeakyReluTiling tiling;
49	    LeakyKernel<accType, outType> leakyKernel_;
50	    TPipe aivPipe_;
51	    BlockScheduler sched_;
