56	/**
57	  * @brief  Set matmulLeaky input and output gm addr of current core.
58	  * @param  a: A matrix gm addr.
59	  * @param  b: B matrix gm addr.
60	  * @param  c: C matrix gm addr.
61	  * @param  ws: Temporary gm space addr required by matmul calc.
62	  * @param  tGM: matmul tiling data.
63	  * @retval None
64	  */
65	template <typename aType, typename bType, typename accType, typename outType>
66	__aicore__ inline void MatmulLeakyKernel<aType, bType, accType, outType>::Init(
67	    GM_ADDR a, GM_ADDR b, GM_ADDR c, GM_ADDR ws, GM_ADDR tGM)
68	{
69	    CopyTiling(&tiling, tGM);
70	
71	    aGM_.SetGlobalBuffer((__gm__ aType *)a, tiling.M * tiling.K);
72	    bGM_.SetGlobalBuffer((__gm__ bType *)b, tiling.K * tiling.N);
73	    cGM_.SetGlobalBuffer((__gm__ outType *)c, tiling.M * tiling.N);
74	    if constexpr (!std::is_same_v<accType, outType>) {
75	        wsGM_.SetGlobalBuffer((__gm__ accType *)ws, tiling.M * tiling.N);
76	    }
77	
78	    groupIdx_ = GetBlockIdx() / GetSubBlockNum();
79	    sched_.Init(tiling.M, tiling.N, tiling.baseM, tiling.baseN, GetBlockNum(), groupIdx_);
80	
81	    if ASCEND_IS_AIV {
82	        subTileM_ = tiling.baseM / GetSubBlockNum();
83	        leakyKernel_.Init(subTileM_, tiling.baseN, &aivPipe_);
84	    }
85	}
