87	/**
88	  * @brief  Main process of matmul calculation.
89	  *         AIC: GM→L1→L0A/L0B, Mmad, Fixpipe L0C→GM.
90	  *         AIV: Read workspace, Cast, LeakyRelu, Write output.
91	  * @retval None
92	  */
93	template <typename aType, typename bType, typename accType, typename outType>
94	__aicore__ inline void MatmulLeakyKernel<aType, bType, accType, outType>::Process()
95	{
96	    int mi, ni;
97	
98	    if ASCEND_IS_AIC {
99	        uint32_t a1s = (uint32_t)(tiling.baseM * tiling.baseK);
100	        uint32_t b1s = (uint32_t)(tiling.baseK * tiling.baseN);
101	        uint32_t mns = (uint32_t)(tiling.baseM * tiling.baseN);
102	
103	        LocalMemAllocator<Hardware::L1> L1;
104	        LocalMemAllocator<Hardware::L0A> L0A;
105	        LocalMemAllocator<Hardware::L0B> L0B;
106	        LocalMemAllocator<Hardware::L0C> L0C;
107	
108	        LocalTensor<aType> a1 = L1.Alloc<TPosition::A1, aType>(a1s);
109	        LocalTensor<bType> b1 = L1.Alloc<TPosition::B1, bType>(b1s);
110	        LocalTensor<aType> a2 = L0A.Alloc<TPosition::A2, aType>(a1s);
111	        LocalTensor<bType> b2 = L0B.Alloc<TPosition::B2, bType>(b1s);
112	        LocalTensor<accType> cL = L0C.Alloc<TPosition::CO1, accType>(mns);
113	
114	        uint32_t kT = tiling.K / tiling.baseK;
115	
116	        while (sched_.HasNext()) {
117	            sched_.Next(mi, ni);
118	
119	            auto aB = aGM_[mi * tiling.baseM * tiling.K];
120	            auto bB = bGM_[ni * tiling.baseN];
121	
122	            for (uint32_t kt = 0; kt < kT; kt++) {
123	                LoadNdGmToNzL1(a1, aB[kt * tiling.baseK], tiling.baseM, tiling.baseK, tiling.K);
124	                LoadNdGmToNzL1(b1, bB[kt * tiling.baseK * tiling.N], tiling.baseK, tiling.baseN, tiling.N);
125	                PipeBarrier<PIPE_ALL>();
126	
127	                LoadNzL1ToZzL0A(a2, a1, tiling.baseM, tiling.baseK, tiling.baseM);
128	                LoadNzL1ToZnL0B(b2, b1, tiling.baseK, tiling.baseN, tiling.baseK);
129	                PipeBarrier<PIPE_ALL>();
130	
131	                MmadParams mp;
132	                mp.m = tiling.baseM;
133	                mp.n = tiling.baseN;
134	                mp.k = tiling.baseK;
135	                mp.cmatrixInitVal = (kt == 0);
136	                Mmad(cL, a2, b2, mp);
137	                PipeBarrier<PIPE_ALL>();
138	            }
139	            PipeBarrier<PIPE_ALL>();
140	
141	            if constexpr (std::is_same_v<accType, outType>) {
142	                auto cB = cGM_[mi * tiling.baseM * tiling.N + ni * tiling.baseN];
143	                FixpipeNzL0cToNdGmStride(cB, cL, tiling.baseM, tiling.baseN, tiling.N);
144	            } else {
145	                auto wB = wsGM_[mi * tiling.baseM * tiling.N + ni * tiling.baseN];
146	                FixpipeNzL0cToNdGmStride(wB, cL, tiling.baseM, tiling.baseN, tiling.N);
147	            }
148	            PipeBarrier<PIPE_ALL>();
149	        }
150	
151	        CrossCoreSetFlag<0x2, PIPE_FIX>(CUBE_NOTIFY_VECTOR_ID);
152	    }
153	
154	    if ASCEND_IS_AIV {
155	        CrossCoreWaitFlag<0x2>(CUBE_NOTIFY_VECTOR_ID);
156	
157	        while (sched_.HasNext()) {
158	            sched_.Next(mi, ni);
159	
160	            int ro = GetSubBlockIdx() * subTileM_;
161	            auto cB = cGM_[(mi * tiling.baseM + ro) * tiling.N + ni * tiling.baseN];
162	
163	            if constexpr (std::is_same_v<accType, outType>) {
164	                leakyKernel_.Process(cB, cB, tiling.N);
165	            } else {
166	                auto wB = wsGM_[(mi * tiling.baseM + ro) * tiling.N + ni * tiling.baseN];
167	                leakyKernel_.Process(wB, cB, tiling.N);
168	            }
169	        }
170	    }
171	}
