/**
 * @file swiglu.cpp
 * @brief AscendC kernel for SwiGLU activation: y = silu(a) * b
 *
 * SwiGLU(x, dim) where a and b are chunks along the last dimension.
 * Host reshapes input to [total_rows, D] before calling this kernel.
 * Kernel processes [total_rows, D] -> [total_rows, D/2].
 *
 * Compute per tile:
 *   1. DataCopy a_ub <- x[row, start:start+size]     (first half)
 *   2. DataCopy b_ub <- x[row, D/2+start:D/2+start+size]  (second half)
 *   3. Silu(a_ub, s_ub, size)                        (silu(a))
 *   4. Mul(y_ub, s_ub, b_ub, size)                   (silu(a) * b)
 *   5. DataCopy y[row, start:start+size] <- y_ub
 */

#include "kernel_operator.h"
using namespace AscendC;

constexpr uint32_t DEFAULT_TILE_SIZE = 2048;
constexpr uint32_t DEFAULT_BLOCK_ROWS = 8;

struct SwiGLUTiling {
    int32_t totalRows;
    int32_t D;       // chunk dimension
    int32_t halfD;   // D / 2
    int32_t tile_size;
    int32_t block_rows;
    int32_t dtype;   // 0=float32, 1=float16, 2=bfloat16
};

template <typename T>
class SwiGLUKernel {
public:
    __aicore__ inline SwiGLUKernel() {}
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tGM);
    __aicore__ inline void Process();

private:
    GlobalTensor<T> xGM_;
    GlobalTensor<T> yGM_;
    SwiGLUTiling tiling_;
    TPipe pipe_;
    TQue<TPosition::VECIN, 1> inQueue_;
    TQue<TPosition::VECOUT, 1> outQueue_;
    LocalTensor<T> aLocal_;
    LocalTensor<T> bLocal_;
    LocalTensor<T> sLocal_;
    LocalTensor<T> yLocal_;
    LocalTensor<uint8_t> sigTmpBuf_;
    uint32_t tileSize_;
    uint32_t halfD_;
};

template <typename T>
__aicore__ inline void SwiGLUKernel<T>::Init(GM_ADDR x, GM_ADDR y, GM_ADDR tGM)
{
    auto *tilingPtr = reinterpret_cast<SwiGLUTiling *>(tGM);
    tiling_ = *tilingPtr;
    halfD_ = static_cast<uint32_t>(tiling_.halfD);

    int64_t inputSize = static_cast<int64_t>(tiling_.totalRows) * tiling_.D;
    int64_t outputSize = static_cast<int64_t>(tiling_.totalRows) * tiling_.halfD;
    xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), inputSize);
    yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), outputSize);

    tileSize_ = static_cast<uint32_t>(tiling_.tile_size);

    // Allocate pipe buffers for a, b, s, y (double buffer)
    pipe_.InitBuffer(inQueue_, 1, tileSize_ * sizeof(T));
    pipe_.InitBuffer(outQueue_, 1, tileSize_ * sizeof(T));

    aLocal_ = inQueue_.AllocTensor<T>();
    bLocal_ = inQueue_.AllocTensor<T>();
    sLocal_ = outQueue_.AllocTensor<T>();
    yLocal_ = outQueue_.AllocTensor<T>();

    // Allocate Sigmoid temp buffer
    uint32_t maxTmpSize = 0;
    uint32_t minTmpSize = 0;
    std::vector<int64_t> shapeVec = {static_cast<int64_t>(tileSize_)};
    AscendC::TensorShape shape(shapeVec);
    AscendC::GetSigmoidMaxMinTmpSize(shape, sizeof(T), false, maxTmpSize, minTmpSize);
    sigTmpBuf_ = pipe_.AllocBuf<uint8_t>(minTmpSize);
}

template <typename T>
__aicore__ inline void SwiGLUKernel<T>::Process()
{
    int32_t blockIdx = GetBlockIdx();
    int32_t rowBase = blockIdx * tiling_.block_rows;
    int32_t totalRows = tiling_.totalRows;
    int32_t D = tiling_.D;
    int32_t halfD = tiling_.halfD;
    uint32_t tileSize = tileSize_;

    for (int32_t r = 0; r < tiling_.block_rows; ++r) {
        int32_t rowIdx = rowBase + r;
        if (rowIdx >= totalRows) {
            break;
        }

        int64_t rowOffset = static_cast<int64_t>(rowIdx) * D;
        int64_t aOffset = rowOffset;
        int64_t bOffset = rowOffset + halfD;
        int64_t yOffset = static_cast<int64_t>(rowIdx) * halfD;

        int32_t numTiles = (halfD + tileSize - 1) / static_cast<int32_t>(tileSize);
        for (int32_t t = 0; t < numTiles; ++t) {
            int32_t start = t * tileSize;
            int32_t curSize = (tileSize < halfD - start) ? static_cast<int32_t>(tileSize)
                                                          : (halfD - start);
            uint32_t uCurSize = static_cast<uint32_t>(curSize);

            // CopyIn: load a and b segments
            DataCopyParams copyParamA;
            copyParamA.blockCount = 1;
            copyParamA.blockLen = uCurSize * sizeof(T);
            DataCopy(aLocal_, xGM_[aOffset + start], copyParamA);

            DataCopyParams copyParamB;
            copyParamB.blockCount = 1;
            copyParamB.blockLen = uCurSize * sizeof(T);
            DataCopy(bLocal_, xGM_[bOffset + start], copyParamB);

            inQueue_.EnQue(aLocal_);
            inQueue_.EnQue(bLocal_);
