 *   4. Mul(s_ub, a_ub, s_ub, size)                     (a * sigmoid = silu(a))
 *   5. Mul(y_ub, s_ub, b_ub, size)                     (silu(a) * b)
 *   6. DataCopy y[row, start:start+size] <- y_ub
 */

