#include "torch_kernel_helper.h"
#include "tiling/platform/platform_ascendc.h"
#include "aclrtlaunch_swiglu_fp32.h"
#include "aclrtlaunch_swiglu_fp16.h"

namespace ascend_kernel {

static inline int64_t GetWorkspaceSize(const SwiGLUTiling *tiling, int accElementSize,
                                       uint32_t usedCoreNum)
{
    (void)usedCoreNum;
    return static_cast<int64_t>(sizeof(SwiGLUTiling));
}

at::Tensor swiglu(const at::Tensor &x, int64_t dim)
{
    // Normalize dim
    int64_t normalizedDim = dim;
    if (dim < 0) {
        normalizedDim = x.dim() + dim;
    }

    // Check that chunk dim is the last dim (wrapper ensures this)
    TORCH_CHECK(normalizedDim == x.dim() - 1,
                "swiglu: chunk dim must be the last dim; reshape in wrapper");
    TORCH_CHECK(x.is_contiguous(), "swiglu: input must be contiguous");

    int64_t D = x.sizes()[x.dim() - 1];
    TORCH_CHECK(D % 2 == 0, "swiglu: chunk dim must be even, got ", D);

    // Compute total_rows (product of all dims except last)
    int64_t totalRows = 1;
    for (int64_t i = 0; i < x.dim() - 1; ++i) {
        totalRows *= x.sizes()[i];
    }

    int64_t halfD = D / 2;

    // Create output tensor
    std::vector<int64_t> outShape(x.sizes().begin(), x.sizes().end());
    outShape.back() = halfD;
    at::Tensor y = at::empty(outShape, x.options());

    // dtype mapping
    int32_t dtypeVal = 0;  // default float32
    if (x.scalar_type() == at::kHalf) {
        dtypeVal = 1;
    } else if (x.scalar_type() == at::kBFloat16) {
        dtypeVal = 2;
    } else {
        TORCH_CHECK(x.scalar_type() == at::kFloat,
                    "swiglu: unsupported dtype, only float32/float16/bfloat16");
    }

    // Tiling data
    at::Tensor t = at::empty({static_cast<int64_t>(sizeof(SwiGLUTiling))},
                             at::device(at::kCPU).dtype(at::kByte));
    auto *tilingPtr = reinterpret_cast<SwiGLUTiling *>(t.data_ptr());
    tilingPtr->totalRows = static_cast<int32_t>(totalRows);
    tilingPtr->D = static_cast<int32_t>(D);
    tilingPtr->halfD = static_cast<int32_t>(halfD);
    tilingPtr->tile_size = 2048;
    tilingPtr->block_rows = 8;
    tilingPtr->dtype = dtypeVal;

    auto tilingNpu = t.to(at::kPrivateUse1);

    // Convert bfloat16 to float32 for kernel compatibility
    at::Tensor xKernel = x;
    at::Tensor yKernel = y;
    if (x.scalar_type() == at::kBFloat16) {
        xKernel = x.to(at::kFloat);
        yKernel = at::empty(outShape, xKernel.options());
    }

    auto ascendcPlatform = platform_ascendc::PlatformAscendCManager::GetInstance();
    uint32_t usedCoreNum = ascendcPlatform->GetCoreNumAic();
    uint32_t blockDim = usedCoreNum;

    int accElementSize = sizeof(float);
    int64_t workSpaceSize = GetWorkspaceSize(tilingPtr, accElementSize, usedCoreNum);
    at::Tensor w = at::empty({workSpaceSize}, at::device(at::kPrivateUse1).dtype(at::kByte));

    if (x.scalar_type() == at::kFloat) {
        EXEC_KERNEL_CMD(swiglu_fp32, blockDim, xKernel, yKernel, tilingNpu);
    } else {
        EXEC_KERNEL_CMD(swiglu_fp16, blockDim, xKernel, yKernel, tilingNpu);
    }

    if (x.scalar_type() == at::kBFloat16) {
        return yKernel.to(at::kBFloat16);
    }
    return y;
}

} // namespace ascend_kernel
