/**
 * @file swiglu.cpp
 * @brief AscendC kernel for SwiGLU: y[row, i] = silu(x[row, i]) * x[row, i + D/2]
 *
 * Input is pre-shaped by host to [total_rows, D] with chunk dim as last dim.
 * Output is [total_rows, D/2].
 * Each block processes block_rows rows. Each row is tiled along D/2.
 *
 * Compute per tile:
 *   Sigmoid(s, a, tmpBuf, size)   -> s = sigmoid(a)
 *   Mul(y, a, s, size)             -> y = a * sigmoid(a) = silu(a)
 *   Mul(s, y, b, size)             -> s = silu(a) * b
 *   DataCopy(yGM, s, size)         -> write result
 */

#include "kernel_operator.h"
using namespace AscendC;

struct SwiGLUTiling {
    int32_t totalRows;
    int32_t D;
    int32_t halfD;
    int32_t tile_size;
    int32_t block_rows;
    int32_t dtype;
};

template <typename T>
class SwiGLUKernel {
public:
    __aicore__ inline SwiGLUKernel() {}
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tGM);
    __aicore__ inline void Process();

private:
    GlobalTensor<T> xGM_;
    GlobalTensor<T> yGM_;
    SwiGLUTiling tiling_;
    TPipe pipe_;
    TQue<TPosition::VECIN, 2> inQueue_;
    TQue<TPosition::VECOUT, 2> outQueue_;
    LocalTensor<T> aLocal_;
    LocalTensor<T> bLocal_;
    LocalTensor<T> sLocal_;
    LocalTensor<T> yLocal_;
    LocalTensor<uint8_t> sigTmpBuf_;
    uint32_t tileSize_;
};

template <typename T>
__aicore__ inline void SwiGLUKernel<T>::Init(GM_ADDR x, GM_ADDR y, GM_ADDR tGM)
{
    auto *tilingPtr = reinterpret_cast<SwiGLUTiling *>(tGM);
    tiling_ = *tilingPtr;

    int64_t inputSize = static_cast<int64_t>(tiling_.totalRows) * tiling_.D;
    int64_t outputSize = static_cast<int64_t>(tiling_.totalRows) * tiling_.halfD;
    xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), inputSize);
    yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), outputSize);

    tileSize_ = static_cast<uint32_t>(tiling_.tile_size);

    // VECIN queue for a and b inputs (depth=2)
    pipe_.InitBuffer(inQueue_, 2, tileSize_ * sizeof(T));
    // VECOUT queue for s and y outputs (depth=2)
    pipe_.InitBuffer(outQueue_, 2, tileSize_ * sizeof(T));

    // Sigmoid temp buffer (VECCALC)
    uint32_t maxTmpSize = 0;
    uint32_t minTmpSize = 0;
    std::vector<int64_t> shapeVec = {static_cast<int64_t>(tileSize_)};
    AscendC::TensorShape shape(shapeVec);
    AscendC::GetSigmoidMaxMinTmpSize(shape, sizeof(T), false, maxTmpSize, minTmpSize);
    pipe_.InitBuffer(sigTmpBuf_, minTmpSize);

    aLocal_ = inQueue_.AllocTensor<T>();
    bLocal_ = inQueue_.AllocTensor<T>();
    sLocal_ = outQueue_.AllocTensor<T>();
    yLocal_ = outQueue_.AllocTensor<T>();
}

template <typename T>
__aicore__ inline void SwiGLUKernel<T>::Process()
{
    int32_t blockIdx = GetBlockIdx();
    int32_t rowBase = blockIdx * tiling_.block_rows;
    int32_t totalRows = tiling_.totalRows;
    int32_t D = tiling_.D;
    int32_t halfD = tiling_.halfD;
    uint32_t tileSize = tileSize_;

    for (int32_t r = 0; r < tiling_.block_rows; ++r) {
        int32_t rowIdx = rowBase + r;
        if (rowIdx >= totalRows) {
            break;
        }

        int64_t rowOffset = static_cast<int64_t>(rowIdx) * D;
        int64_t aOffset = rowOffset;
        int64_t bOffset = rowOffset + halfD;
        int64_t yOffset = static_cast<int64_t>(rowIdx) * halfD;

        int32_t numTiles = (halfD + static_cast<int32_t>(tileSize) - 1) / static_cast<int32_t>(tileSize);
        for (int32_t t = 0; t < numTiles; ++t) {
            int32_t start = t * tileSize;
            int32_t curSize = (tileSize < static_cast<uint32_t>(halfD - start))
                                  ? static_cast<int32_t>(tileSize)
                                  : (halfD - start);
            uint32_t uCurSize = static_cast<uint32_t>(curSize);

            // --- CopyIn: load a and b from GM ---
            DataCopy(aLocal_, xGM_[aOffset + start], uCurSize);
            inQueue_.EnQue(aLocal_);

            DataCopy(bLocal_, xGM_[bOffset + start], uCurSize);
            inQueue_.EnQue(bLocal_);

            // --- DeQue: wait for DMA ---
            inQueue_.DeQue<T>(aLocal_);
            inQueue_.DeQue<T>(bLocal_);

            // --- Compute: sigmoid(a) -> s ---
            Sigmoid(sLocal_, aLocal_, sigTmpBuf_, uCurSize);
            PipeBarrier<PIPE_V>();

            // --- Compute: silu(a) = a * sigmoid(a) -> y ---
            Mul(yLocal_, aLocal_, sLocal_, uCurSize);
            PipeBarrier<PIPE_V>();

            // --- Compute: result = silu(a) * b -> s (VECOUT for CopyOut) ---
            Mul(sLocal_, yLocal_, bLocal_, uCurSize);
            PipeBarrier<PIPE_V>();

            // --- CopyOut: write result to output GM ---
            outQueue_.EnQue(sLocal_);
            outQueue_.DeQue<T>(sLocal_);
            DataCopy(yGM_[yOffset + start], sLocal_, uCurSize);

            // --- Free tensors for next iteration ---
            outQueue_.FreeTensor(sLocal_);
            outQueue_.FreeTensor(yLocal_);
            inQueue_.FreeTensor(aLocal_);
            inQueue_.FreeTensor(bLocal_);
        }
    }
}

extern "C" __global__ __aicore__ void swiglu_fp32(GM_ADDR x, GM_ADDR y, GM_ADDR tiling)
{
    SwiGLUKernel<float> kernel;
    kernel.Init(x, y, tiling);
    kernel.Process();
}

extern "C" __global__ __aicore__ void swiglu_fp16(GM_ADDR x, GM_ADDR y, GM_ADDR tiling)
{
    SwiGLUKernel<half> kernel;
    kernel.Init(x, y, tiling);
    kernel.Process();
}
