/**
 * @file swiglu.cpp
 * @brief AscendC kernel for SwiGLU: y = silu(a) * b
 *
 * Input is pre-shaped to [total_rows, D] with chunk dim as last dim.
 * Kernel processes [total_rows, D] -> [total_rows, D/2].
 * Each block handles block_rows rows. Within each row, tiles along D/2.
 *
 * Uses TBuf for direct buffer allocation + PipeBarrier for sync.
 * Avoids TQue API complexity.
 *
 * Compute per tile: Sigmoid -> Mul -> Mul -> CopyOut
 */

#include "kernel_operator.h"
using namespace AscendC;

struct SwiGLUTiling {
    int32_t totalRows;
    int32_t D;
    int32_t halfD;
    int32_t tile_size;
    int32_t block_rows;
    int32_t dtype;
};

__aicore__ inline void CopyTiling(SwiGLUTiling *dst, GM_ADDR src)
{
    auto *d = reinterpret_cast<int32_t *>(dst);
    auto *s = reinterpret_cast<__gm__ int32_t *>(src);
    for (size_t i = 0; i < sizeof(SwiGLUTiling) / sizeof(int32_t); ++i) {
        d[i] = s[i];
    }
}

template <typename T>
class SwiGLUKernel {
public:
    __aicore__ inline SwiGLUKernel() {}
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tGM);
    __aicore__ inline void Process();

private:
    GlobalTensor<T> xGM_;
    GlobalTensor<T> yGM_;
    SwiGLUTiling tiling_;
    TPipe pipe_;
    TBuf<TPosition::VECIN> aBuf_;
    TBuf<TPosition::VECIN> bBuf_;
    TBuf<TPosition::VECOUT> sBuf_;
    TBuf<TPosition::VECOUT> yBuf_;
    TBuf<TPosition::VECCALC> sigTmpBuf_;
    uint32_t tileSize_;
};

template <typename T>
__aicore__ inline void SwiGLUKernel<T>::Init(GM_ADDR x, GM_ADDR y, GM_ADDR tGM)
{
    CopyTiling(&tiling_, tGM);

    int64_t inputSize = static_cast<int64_t>(tiling_.totalRows) * tiling_.D;
    int64_t outputSize = static_cast<int64_t>(tiling_.totalRows) * tiling_.halfD;
    xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), inputSize);
    yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), outputSize);

    tileSize_ = static_cast<uint32_t>(tiling_.tile_size);

    // Direct pipe buffer allocation via TBuf
    pipe_.InitBuffer(aBuf_, tileSize_ * sizeof(T));
    pipe_.InitBuffer(bBuf_, tileSize_ * sizeof(T));
    pipe_.InitBuffer(sBuf_, tileSize_ * sizeof(T));
    pipe_.InitBuffer(yBuf_, tileSize_ * sizeof(T));
    pipe_.InitBuffer(sigTmpBuf_, 4096);
}

template <typename T>
__aicore__ inline void SwiGLUKernel<T>::Process()
{
    int32_t blockIdx = GetBlockIdx();
    int32_t rowBase = blockIdx * tiling_.block_rows;
    int32_t totalRows = tiling_.totalRows;
    int32_t D = tiling_.D;
    int32_t halfD = tiling_.halfD;
    uint32_t tileSize = tileSize_;

    for (int32_t r = 0; r < tiling_.block_rows; ++r) {
        int32_t rowIdx = rowBase + r;
        if (rowIdx >= totalRows) {
            break;
        }

        int64_t rowOffset = static_cast<int64_t>(rowIdx) * D;
        int64_t aOffset = rowOffset;
        int64_t bOffset = rowOffset + halfD;
        int64_t yOffset = static_cast<int64_t>(rowIdx) * halfD;

        int32_t numTiles = (halfD + static_cast<int32_t>(tileSize) - 1) / static_cast<int32_t>(tileSize);
        for (int32_t t = 0; t < numTiles; ++t) {
            int32_t start = t * tileSize;
            int32_t curSize = (tileSize < static_cast<uint32_t>(halfD - start))
                                  ? static_cast<int32_t>(tileSize)
                                  : (halfD - start);
            uint32_t uCurSize = static_cast<uint32_t>(curSize);

            // --- CopyIn: load a segment ---
            DataCopy(aBuf_, xGM_[aOffset + start], uCurSize);
            PipeBarrier<PIPE_ALL>();

            // --- CopyIn: load b segment ---
            DataCopy(bBuf_, xGM_[bOffset + start], uCurSize);
            PipeBarrier<PIPE_ALL>();

            // --- Compute: sigmoid(a) -> s ---
            Sigmoid(sBuf_, aBuf_, sigTmpBuf_, uCurSize);
            PipeBarrier<PIPE_ALL>();

            // --- Compute: silu(a) = a * sigmoid(a) -> y ---
            Mul(yBuf_, aBuf_, sBuf_, uCurSize);
            PipeBarrier<PIPE_ALL>();

            // --- Compute: result = silu(a) * b -> s (VECOUT for CopyOut) ---
            Mul(sBuf_, yBuf_, bBuf_, uCurSize);
            PipeBarrier<PIPE_ALL>();

            // --- CopyOut: write result to GM ---
            DataCopy(yGM_[yOffset + start], sBuf_, uCurSize);
            PipeBarrier<PIPE_ALL>();
        }
    }
}

