6	/**
7	 * @file swiglu.cpp
8	 * @brief AscendC kernel for SwiGLU: y = silu(a) * b
9	 *
10	 * Input is pre-shaped to [total_rows, D] with chunk dim as last dim.
11	 * Kernel processes [total_rows, D] -> [total_rows, D/2].
12	 * Each block handles block_rows rows. Within each row, tiles along D/2.
13	 *
14	 * depth=1 TQue with return-value AllocTensor/DeQue.
15	 * PipeBarrier provides pipeline synchronization.
16	 *
17	 * Compute per tile: Sigmoid -> Mul -> Mul -> CopyOut
18	 */
19	
20	#include "kernel_operator.h"
21	using namespace AscendC;
22	
23	struct SwiGLUTiling {
24	    int32_t totalRows;
25	    int32_t D;
26	    int32_t halfD;
27	    int32_t tile_size;
28	    int32_t block_rows;
29	    int32_t dtype;
30	};
31	
32	__aicore__ inline void CopyTiling(SwiGLUTiling *dst, GM_ADDR src)
33	{
34	    auto *d = reinterpret_cast<int32_t *>(dst);
35	    auto *s = reinterpret_cast<__gm__ int32_t *>(src);
36	    for (size_t i = 0; i < sizeof(SwiGLUTiling) / sizeof(int32_t); ++i) {
37	        d[i] = s[i];
38	    }
39	}
40	
41	template <typename T>
42	class SwiGLUKernel {
43	public:
44	    __aicore__ inline SwiGLUKernel() {}
45	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tGM);
46	    __aicore__ inline void Process();
47	
48	private:
49	    GlobalTensor<T> xGM_;
50	    GlobalTensor<T> yGM_;
51	    SwiGLUTiling tiling_;
52	    TPipe pipe_;
53	    TQue<TPosition::VECIN, 1> inQueueA_;
54	    TQue<TPosition::VECIN, 1> inQueueB_;
55	    TQue<TPosition::VECOUT, 1> outQueueS_;
56	    TQue<TPosition::VECOUT, 1> outQueueY_;
57	    TQue<TPosition::VECCALC, 1> sigQueue_;
58	    LocalTensor<T> aLocal_;
59	    LocalTensor<T> bLocal_;
60	    LocalTensor<T> sLocal_;
61	    LocalTensor<T> yLocal_;
62	    LocalTensor<uint8_t> sigTmpBuf_;
63	    uint32_t tileSize_;
64	};
65	
66	template <typename T>
67	__aicore__ inline void SwiGLUKernel<T>::Init(GM_ADDR x, GM_ADDR y, GM_ADDR tGM)
68	{
69	    CopyTiling(&tiling_, tGM);
70	
71	    int64_t inputSize = static_cast<int64_t>(tiling_.totalRows) * tiling_.D;
72	    int64_t outputSize = static_cast<int64_t>(tiling_.totalRows) * tiling_.halfD;
73	    xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), inputSize);
74	    yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), outputSize);
75	
76	    tileSize_ = static_cast<uint32_t>(tiling_.tile_size);
77	
78	    // depth=1 TQue with return-value AllocTensor and DeQue
79	    uint8_t bufNum = 1;
80	    uint32_t bufSize = static_cast<uint32_t>(tileSize_) * static_cast<uint32_t>(sizeof(T));
81	    pipe_.InitBuffer(inQueueA_, bufNum, bufSize);
82	    pipe_.InitBuffer(inQueueB_, bufNum, bufSize);
83	    pipe_.InitBuffer(outQueueS_, bufNum, bufSize);
84	    pipe_.InitBuffer(outQueueY_, bufNum, bufSize);
85	    // Sigmoid temp buffer: use 4x data size for safety
86	    pipe_.InitBuffer(sigQueue_, bufNum, bufSize * 4);
87	
88	    aLocal_ = inQueueA_.AllocTensor<T>();
89	    bLocal_ = inQueueB_.AllocTensor<T>();
90	    sLocal_ = outQueueS_.AllocTensor<T>();
91	    yLocal_ = outQueueY_.AllocTensor<T>();
92	    sigTmpBuf_ = sigQueue_.AllocTensor<uint8_t>();
93	}
94	
95	template <typename T>
96	__aicore__ inline void SwiGLUKernel<T>::Process()
97	{
98	    int32_t blockIdx = GetBlockIdx();
99	    int32_t rowBase = blockIdx * tiling_.block_rows;
100	    int32_t totalRows = tiling_.totalRows;
101	    int32_t D = tiling_.D;
102	    int32_t halfD = tiling_.halfD;
103	    uint32_t tileSize = tileSize_;
104	    int32_t blockRows = tiling_.block_rows;
105	    int32_t blockNum = (totalRows + blockRows - 1) / blockRows;
106	    int32_t coreNum = GetBlockNum();
107	
108	    // Persistent-kernel: each core processes blocks strided by coreNum
109	    for (int32_t b = blockIdx; b < blockNum; b += coreNum) {
