/**
 * @file swiglu.cpp
 * @brief AscendC kernel for SwiGLU: y = silu(a) * b
 *
 * Input is pre-shaped to [total_rows, D] with chunk dim as last dim.
 * Kernel processes [total_rows, D] -> [total_rows, D/2].
 * Each block handles block_rows rows. Within each row, tiles along D/2.
 *
 * Uses DataCopyPad for alignment-safe GM↔UB transfers.
 * Uses Silu API for direct silu computation (no Sigmoid temp buffer needed).
 * depth=1 TQue with return-value AllocTensor/DeQue.
 * PipeBarrier provides pipeline synchronization.
 */

#include "kernel_operator.h"
using namespace AscendC;

struct SwiGLUTiling {
    int32_t totalRows;
    int32_t D;
    int32_t halfD;
    int32_t tile_size;
    int32_t block_rows;
    int32_t dtype;
};

__aicore__ inline void CopyTiling(SwiGLUTiling *dst, GM_ADDR src)
{
    auto *d = reinterpret_cast<int32_t *>(dst);
    auto *s = reinterpret_cast<__gm__ int32_t *>(src);
    for (size_t i = 0; i < sizeof(SwiGLUTiling) / sizeof(int32_t); ++i) {
        d[i] = s[i];
    }
}

template <typename T>
class SwiGLUKernel {
public:
    __aicore__ inline SwiGLUKernel() {}
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, GM_ADDR tGM);
    __aicore__ inline void Process();

private:
    GlobalTensor<T> xGM_;
    GlobalTensor<T> yGM_;
    SwiGLUTiling tiling_;
    TPipe pipe_;
    TQue<TPosition::VECIN, 1> inQueueA_;
    TQue<TPosition::VECIN, 1> inQueueB_;
    TQue<TPosition::VECOUT, 1> outQueueS_;
    TQue<TPosition::VECOUT, 1> outQueueY_;
    LocalTensor<T> aLocal_;
    LocalTensor<T> bLocal_;
    LocalTensor<T> sLocal_;
    LocalTensor<T> yLocal_;
    uint32_t tileSize_;
};

template <typename T>
__aicore__ inline void SwiGLUKernel<T>::Init(GM_ADDR x, GM_ADDR y, GM_ADDR tGM)
{
    CopyTiling(&tiling_, tGM);

    int64_t inputSize = static_cast<int64_t>(tiling_.totalRows) * tiling_.D;
    int64_t outputSize = static_cast<int64_t>(tiling_.totalRows) * tiling_.halfD;
    xGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(x), inputSize);
    yGM_.SetGlobalBuffer(reinterpret_cast<__gm__ T *>(y), outputSize);

    tileSize_ = static_cast<uint32_t>(tiling_.tile_size);

    // depth=1 TQue with return-value AllocTensor and DeQue
    uint8_t bufNum = 1;
    uint32_t bufSize = static_cast<uint32_t>(tileSize_) * static_cast<uint32_t>(sizeof(T));
    pipe_.InitBuffer(inQueueA_, bufNum, bufSize);
    pipe_.InitBuffer(inQueueB_, bufNum, bufSize);
    pipe_.InitBuffer(outQueueS_, bufNum, bufSize);
    pipe_.InitBuffer(outQueueY_, bufNum, bufSize);

    aLocal_ = inQueueA_.AllocTensor<T>();
    bLocal_ = inQueueB_.AllocTensor<T>();
    sLocal_ = outQueueS_.AllocTensor<T>();
    yLocal_ = outQueueY_.AllocTensor<T>();
}

template <typename T>
__aicore__ inline void SwiGLUKernel<T>::Process()
{
    int32_t blockIdx = GetBlockIdx();
    int32_t rowBase = blockIdx * tiling_.block_rows;
    int32_t totalRows = tiling_.totalRows;
    int32_t D = tiling_.D;
    int32_t halfD = tiling_.halfD;
    uint32_t tileSize = tileSize_;
    int32_t blockRows = tiling_.block_rows;
    int32_t blockNum = (totalRows + blockRows - 1) / blockRows;
    int32_t coreNum = GetBlockNum();

    // Persistent-kernel: each core processes blocks strided by coreNum
    for (int32_t b = blockIdx; b < blockNum; b += coreNum) {
        int32_t rowBase = b * blockRows;
        int32_t rowsInBlock = blockRows;
        if (rowBase + blockRows > totalRows) {
            rowsInBlock = totalRows - rowBase;
        }

        for (int32_t r = 0; r < rowsInBlock; ++r) {
            int32_t rowIdx = rowBase + r;

            int64_t rowOffset = static_cast<int64_t>(rowIdx) * D;
            int64_t aOffset = rowOffset;
            int64_t bOffset = rowOffset + halfD;
            int64_t yOffset = static_cast<int64_t>(rowIdx) * halfD;

            int32_t numTiles = (halfD + static_cast<int32_t>(tileSize) - 1) / static_cast<int32_t>(tileSize);
            for (int32_t t = 0; t < numTiles; ++t) {
                int32_t start = t * tileSize;
                int32_t curSize = (tileSize < static_cast<uint32_t>(halfD - start))
                                      ? static_cast<int32_t>(tileSize)
                                      : (halfD - start);
                uint32_t uCurSize = static_cast<uint32_t>(curSize);

                // --- CopyIn: load a segment (DataCopyPad handles non-aligned) ---
                DataCopyPad(aLocal_, xGM_[aOffset + start], uCurSize);
                inQueueA_.EnQue(aLocal_);
                LocalTensor<T> aDeq = inQueueA_.DeQue<T>();

                // --- CopyIn: load b segment ---
                DataCopyPad(bLocal_, xGM_[bOffset + start], uCurSize);
                inQueueB_.EnQue(bLocal_);
                LocalTensor<T> bDeq = inQueueB_.DeQue<T>();

                // --- Compute: silu(a) -> s (uses AscendC built-in Silu) ---
                Silu(sLocal_, aDeq, uCurSize);
                PipeBarrier<PIPE_V>();

                // --- Compute: result = silu(a) * b -> y ---
                Mul(yLocal_, sLocal_, bDeq, uCurSize);
                PipeBarrier<PIPE_V>();

                // --- CopyOut: enqueue, dequeue, write to GM ---
                outQueueY_.EnQue(yLocal_);
                LocalTensor<T> yDeq = outQueueY_.DeQue<T>();
                DataCopyPad(yGM_[yOffset + start], yDeq, uCurSize);

                // --- Ensure CopyOut completes ---
                PipeBarrier<PIPE_ALL>();
            }
        }
    }

    // Free all tensors
    outQueueS_.FreeTensor(sLocal_);
    outQueueY_.FreeTensor(yLocal_);
    inQueueA_.FreeTensor(aLocal_);
    inQueueB_.FreeTensor(bLocal_);
}

extern "C" __global__ __aicore__ void swiglu_fp32(GM_ADDR x, GM_ADDR y, GM_ADDR tiling)
{
    SwiGLUKernel<float> kernel;
    kernel.Init(x, y, tiling);
    kernel.Process();
}

extern "C" __global__ __aicore__ void swiglu_fp16(GM_ADDR x, GM_ADDR y, GM_ADDR tiling)
{
    SwiGLUKernel<half> kernel;
    kernel.Init(x, y, tiling);
    kernel.Process();
}
