                outQueueY_.EnQue(yLocal_);
                LocalTensor<T> yDeq = outQueueY_.DeQue<T>();
                DataCopy(yGM_[yOffset + start], yDeq, alignedSize);

                // --- Ensure CopyOut completes ---
                PipeBarrier<PIPE_ALL>();
